import threading
import time
import signal
import sys
from collections import defaultdict
from typing import Dict, List, Optional
import weakref


class IndexSegment:
    """Represents an immutable segment of the search index."""

    def __init__(self, segment_id: int, documents: Dict[str, List[str]]):
        self._segment_id = segment_id
        self._documents = documents
        self._term_index = self._build_term_index(documents)
        self._active = True
        self._ref_count = 0
        self._lock = threading.Lock()

    def _build_term_index(self, documents):
        index = defaultdict(set)
        for doc_id, terms in documents.items():
            for term in terms:
                index[term.lower()].add(doc_id)
        return dict(index)

    def acquire(self):
        with self._lock:
            if not self._active:
                return False
            self._ref_count += 1
            return True

    def release(self):
        with self._lock:
            self._ref_count -= 1

    def search(self, term: str) -> set:
        return self._term_index.get(term.lower(), set())

    def invalidate(self):
        with self._lock:
            self._active = False

    @property
    def ref_count(self):
        with self._lock:
            return self._ref_count

    @property
    def segment_id(self):
        return self._segment_id


class SegmentPool:
    """Manages lifecycle of index segments with reference counting."""

    def __init__(self):
        self._segments: Dict[int, IndexSegment] = {}
        self._lock = threading.RLock()
        self._disposed_segments: List[int] = []

    def add_segment(self, segment: IndexSegment):
        with self._lock:
            self._segments[segment.segment_id] = segment

    def get_active_segments(self) -> List[IndexSegment]:
        with self._lock:
            return [s for s in self._segments.values() if s._active]

    def dispose_segment(self, segment_id: int):
        with self._lock:
            if segment_id in self._segments:
                seg = self._segments[segment_id]
                seg.invalidate()
                self._disposed_segments.append(segment_id)

    def collect_garbage(self):
        with self._lock:
            still_pending = []
            for seg_id in self._disposed_segments:
                if seg_id in self._segments:
                    seg = self._segments[seg_id]
                    if seg.ref_count == 0:
                        del self._segments[seg_id]
                    else:
                        still_pending.append(seg_id)
            self._disposed_segments = still_pending

    def dispose_all(self):
        with self._lock:
            for seg_id in list(self._segments.keys()):
                self.dispose_segment(seg_id)


class SearchIndexService:
    """Search indexing service with graceful shutdown support."""

    def __init__(self):
        self._pool = SegmentPool()
        self._shutdown_event = threading.Event()
        self._active_queries = []
        self._query_lock = threading.Lock()
        self._gc_thread = None
        self._segment_counter = 0
        self._snapshot_ref: Optional[List[IndexSegment]] = None

    def start(self):
        self._gc_thread = threading.Thread(target=self._gc_loop, daemon=True)
        self._gc_thread.start()

    def _gc_loop(self):
        while not self._shutdown_event.is_set():
            self._pool.collect_garbage()
            time.sleep(0.1)

    def index_documents(self, documents: Dict[str, List[str]]):
        self._segment_counter += 1
        segment = IndexSegment(self._segment_counter, documents)
        self._pool.add_segment(segment)
        return self._segment_counter

    def _acquire_snapshot(self) -> List[IndexSegment]:
        """Acquire a consistent snapshot of segments for querying."""
        segments = self._pool.get_active_segments()
        acquired = []
        for seg in segments:
            if seg.acquire():
                acquired.append(seg)
        return acquired

    def _release_snapshot(self, snapshot: List[IndexSegment]):
        for seg in snapshot:
            seg.release()

    def search(self, term: str) -> List[str]:
        if self._shutdown_event.is_set():
            raise RuntimeError("Service is shutting down")

        snapshot = self._acquire_snapshot()
        try:
            results = set()
            for segment in snapshot:
                results.update(segment.search(term))
            return list(results)
        finally:
            self._release_snapshot(snapshot)

    def graceful_shutdown(self, timeout: float = 5.0):
        """Initiate graceful shutdown - dispose segments and wait for queries."""
        self._shutdown_event.set()

        # Take a snapshot reference before disposal for pending drain
        self._snapshot_ref = self._pool.get_active_segments()

        # Dispose all segments immediately
        self._pool.dispose_all()

        # Wait for GC thread
        if self._gc_thread:
            self._gc_thread.join(timeout=timeout)

        # Force final GC to reclaim memory
        self._pool.collect_garbage()

        # Access snapshot_ref for logging/metrics after GC
        self._drain_pending_operations()

    def _drain_pending_operations(self):
        """Drain any pending operations using the pre-shutdown snapshot."""
        if self._snapshot_ref:
            for seg in self._snapshot_ref:
                # This accesses segment data that may have been GC'd
                # since ref_count was 0 when collect_garbage ran
                try:
                    term_count = len(seg._term_index) if hasattr(seg, '_term_index') else 0
                except (AttributeError, TypeError):
                    term_count = 0
            self._snapshot_ref = None


def create_service_with_data():
    service = SearchIndexService()
    service.start()

    service.index_documents({
        "doc1": ["python", "programming", "language"],
        "doc2": ["java", "programming", "enterprise"],
        "doc3": ["rust", "systems", "programming"],
    })

    service.index_documents({
        "doc4": ["search", "indexing", "lucene"],
        "doc5": ["elasticsearch", "search", "distributed"],
    })

    return service


def main():
    service = create_service_with_data()

    results = service.search("programming")
    print(f"Search results for 'programming': {sorted(results)}")

    results = service.search("search")
    print(f"Search results for 'search': {sorted(results)}")

    # Simulate concurrent search during shutdown
    def delayed_search():
        time.sleep(0.05)
        try:
            r = service.search("python")
            print(f"Delayed search results: {r}")
        except RuntimeError as e:
            print(f"Search rejected: {e}")

    t = threading.Thread(target=delayed_search)
    t.start()

    service.graceful_shutdown(timeout=2.0)
    t.join()
    print("Service shutdown complete.")


if __name__ == "__main__":
    main()
